get_dashboard_report_quick.code:
import (
	"fmt"
)

resp, err := client.DashboardReports().GetDashboardReportQuick(ctx, map[string]any{"duration": "last_12_months", "kpis": "total_sales,aov", "entity_name": "product"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
sales := body["sales"].(map[string]any)
fmt.Println(sales["total"], sales["items_sold"], sales["average_order_value"])
for _, row := range body["kpis"].([]any) {
	kpi := row.(map[string]any)
	fmt.Println(kpi["label"], kpi["value"], kpi["change_percent"])
}

