import (
	"fmt"
)

resp, err := client.DashboardReports().GetDashboardReportSales(ctx, map[string]any{
	"duration":  "last_12_months",
	"breakdown": true,
	"sort":      "sales",
	"order":     "desc",
}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["rows"].([]any) {
	line := row.(map[string]any)
	fmt.Println(line["label"], line["sales"])
}
fmt.Println(body["totals"])

